  1224|function loadPersistedState() {
  1225|  try {
  1226|    const raw = localStorage.getItem('mifeco-pipeline-state');
  1227|    if (!raw) return;
  1228|    const saved = JSON.parse(raw);
  1229|    saved.forEach(s => {
  1230|      const local = pipelinesData.find(p => p.id === s.id);
  1231|      if (!local) return;
  1232|      local.status = s.status ?? local.status;
  1233|      local.currentStage = s.currentStage ?? local.currentStage;
  1234|      local.pct = s.pct ?? local.pct;
  1235|      if (s.thresholds) Object.assign(local.thresholds, s.thresholds);
  1236|    });
  1237|  } catch(e) { /* ignore corrupt data */ }
