function openPipelineStatusModal(tier) {
  const data = pipelineQueueData[tier] || pipelineQueueData['consulting'];
  const modal = document.getElementById('pipelineStatusModal');
  const body = document.getElementById('psModalBody');
  document.getElementById('psModalTitle').textContent = data.title;

  const stageHtml = data.stages.map(s => {
    const dotColor = s.status === 'active' ? 'var(--success)' : s.status === 'done' ? 'var(--accent)' : 'var(--text-secondary)';
    const glow = s.status === 'active' ? 'box-shadow:0 0 8px rgba(34,197,94,.4);' : '';
    return `<div style="display:flex;align-items:center;gap:14px;padding:12px;background:#0f172a;border-radius:8px;border:1px solid #334155;margin-bottom:8px;">
      <div style="width:36px;height:36px;border-radius:50%;background:${dotColor}22;display:flex;align-items:center;justify-content:center;flex-shrink:0;">
        <span style="font-size:16px;font-weight:700;color:${dotColor};">${s.count}</span>
      </div>
      <div style="flex:1;">
        <div style="font-size:13px;font-weight:600;color:var(--text-primary);">${s.name}</div>
        <div style="font-size:11px;color:var(--text-secondary);">${s.desc}</div>
      </div>
      <span style="width:10px;height:10px;border-radius:50%;background:${dotColor};${glow}flex-shrink:0;"></span>
    </div>`;
  }).join('');

  body.innerHTML = `
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:20px;">
      <div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:14px;text-align:center;">
        <div style="font-size:24px;font-weight:800;color:var(--accent);">${data.totalLeads}</div>
        <div style="font-size:10px;color:var(--text-secondary);text-transform:uppercase;letter-spacing:0.5px;">Total Leads</div>
      </div>
      <div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:14px;text-align:center;">
        <div style="font-size:24px;font-weight:800;color:var(--success);">${data.activeInPipeline}</div>
        <div style="font-size:10px;color:var(--text-secondary);text-transform:uppercase;letter-spacing:0.5px;">Active in Pipeline</div>
      </div>
      <div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:14px;text-align:center;">
        <div style="font-size:24px;font-weight:800;color:var(--warning);">${data.completedThisMonth}</div>
        <div style="font-size:10px;color:var(--text-secondary);text-transform:uppercase;letter-spacing:0.5px;">Completed This Month</div>
      </div>
    </div>
    <h4 style="font-size:13px;font-weight:700;color:var(--accent);margin-bottom:10px;">Pipeline Stages & Queue</h4>
    ${stageHtml}
  `;
  modal.classList.add('show');
}

